#include <QCoreApplication>
#include <QDateTime>
#include <QDir>
#include <QFile>
#include <QFileInfo>
#include <unistd.h>
#include <QJsonArray>
#include <QJsonDocument>
#include <QJsonObject>
#include <QLockFile>
#include <QNetworkAccessManager>
#include <QNetworkReply>
#include <QEventLoop>
#include <QProcess>
#include <QSaveFile>
#include <QTextStream>
#include <QTimer>
#include <QUrlQuery>
#include <cmath>
#include <stdexcept>

static QTextStream out(stdout), err(stderr);
static QString configPath() { auto p=qEnvironmentVariable("XDG_CONFIG_HOME", QDir::homePath()+"/.config"); return p+"/omarchy-circadian/config.json"; }
static QJsonObject defaults() { return {{"location", QJsonValue::Null}, {"selected","catppuccin"}, {"pairs", QJsonObject{{"catppuccin",QJsonObject{{"light","catppuccin-latte"},{"dark","catppuccin"}}},{"solarized",QJsonObject{{"light","solarized-light"},{"dark","solarized"}}}}}}; }
static QJsonObject load() { QFile f(configPath()); if (!f.exists()) return defaults(); if (!f.open(QIODevice::ReadOnly)) throw std::runtime_error("cannot read config"); QJsonParseError e; auto doc=QJsonDocument::fromJson(f.readAll(), &e); if (e.error!=QJsonParseError::NoError || !doc.isObject()) throw std::runtime_error("invalid config JSON"); return doc.object(); }
static void save(const QJsonObject &o) { QDir().mkpath(QFileInfo(configPath()).absolutePath()); QSaveFile f(configPath()); if (!f.open(QIODevice::WriteOnly) || f.write(QJsonDocument(o).toJson())<0 || !f.commit()) throw std::runtime_error("cannot save config"); }
static QJsonDocument request(const QUrl &url) { QNetworkAccessManager manager; QNetworkRequest req(url); req.setRawHeader("User-Agent", "omarchy-circadian/1.0 (personal desktop theme scheduler)"); auto *reply=manager.get(req); QEventLoop loop; QTimer timer; timer.setSingleShot(true); QObject::connect(&timer,&QTimer::timeout,&loop,&QEventLoop::quit); QObject::connect(reply,&QNetworkReply::finished,&loop,&QEventLoop::quit); timer.start(10000); loop.exec(); if (!reply->isFinished()) { reply->abort(); throw std::runtime_error("location request timed out"); } if (reply->error()!=QNetworkReply::NoError) throw std::runtime_error(reply->errorString().toStdString()); QJsonParseError e; auto doc=QJsonDocument::fromJson(reply->readAll(),&e); if(e.error!=QJsonParseError::NoError) throw std::runtime_error("invalid location response"); return doc; }
static QJsonObject coords(double lat,double lon, const QString &label) { if (!std::isfinite(lat)||!std::isfinite(lon)||lat < -90||lat > 90||lon < -180||lon > 180) throw std::runtime_error("coordinates must be within latitude ±90 and longitude ±180"); return {{"latitude",lat},{"longitude",lon},{"label",label}}; }
static bool day(QDateTime t,double lat,double lon) { t=t.toUTC(); auto d=t.date(); auto time=t.time(); double hour=time.hour()+time.minute()/60.0+time.second()/3600.0; double g=2*M_PI/(QDate::isLeapYear(d.year())?366:365)*(d.dayOfYear()-1+(hour-12)/24); double eq=229.18*(0.000075+0.001868*cos(g)-0.032077*sin(g)-0.014615*cos(2*g)-0.040849*sin(2*g)); double decl=0.006918-0.399912*cos(g)+0.070257*sin(g)-0.006758*cos(2*g)+0.000907*sin(2*g)-0.002697*cos(3*g)+0.00148*sin(3*g); double minutes=std::fmod(hour*60+eq+4*lon+1440,1440); double angle=(minutes/4-180)*M_PI/180; double phi=lat*M_PI/180; return sin(phi)*sin(decl)+cos(phi)*cos(decl)*cos(angle)>=sin(-0.833*M_PI/180); }
static QString run(const QStringList &args) { QProcess p; p.start("omarchy",args); if (!p.waitForStarted() || !p.waitForFinished(120000) || p.exitStatus()!=QProcess::NormalExit || p.exitCode()!=0) throw std::runtime_error(("omarchy failed: "+QString::fromUtf8(p.readAllStandardError())).toStdString()); return QString::fromUtf8(p.readAllStandardOutput()); }
static void apply(const QJsonObject &c) { auto loc=c.value("location").toObject(); if(loc.isEmpty()) throw std::runtime_error("location not set; run circadian location auto, search, or coords"); auto pair=c.value("pairs").toObject().value(c.value("selected").toString()).toObject(); auto target=pair.value(day(QDateTime::currentDateTimeUtc(),loc.value("latitude").toDouble(),loc.value("longitude").toDouble())?"light":"dark").toString(); if(target.isEmpty()) throw std::runtime_error("selected pair or theme is missing"); auto norm=[](QString s){return s.trimmed().toLower().replace(' ','-');}; if(norm(run({"theme","current"}))!=norm(target)) { out << run({"theme","set",target}); out << "Applied " << target << Qt::endl; } else out << target << " already active" << Qt::endl; }
static void lockedApply() { QString dir=qEnvironmentVariable("XDG_RUNTIME_DIR", QDir::tempPath()); QLockFile lock(dir+"/omarchy-circadian-"+QString::number(getuid())+".qt.lock"); lock.setStaleLockTime(0); if(!lock.tryLock(120000)) throw std::runtime_error("could not acquire theme lock"); apply(load()); }
static int mainImpl(QStringList a) { if(a.size()<2) throw std::runtime_error("usage: circadian {check|status|list|next|select PAIR|pair NAME LIGHT DARK|location auto|search QUERY|coords LAT LON}"); auto c=load(); QString cmd=a[1]; if(cmd=="check" && a.size()==2) lockedApply(); else if(cmd=="status" && a.size()==2) out << QJsonDocument(c).toJson(); else if(cmd=="list" && a.size()==2) { auto pairs=c.value("pairs").toObject(); for(auto i=pairs.begin();i!=pairs.end();++i) { auto p=i.value().toObject(); out << (i.key()==c.value("selected").toString()?"* ":"  ") << i.key() << " : " << p.value("light").toString() << " / " << p.value("dark").toString() << Qt::endl; } } else if(cmd=="pair" && a.size()==5) { auto pairs=c.value("pairs").toObject(); pairs[a[2]]=QJsonObject{{"light",a[3]},{"dark",a[4]}}; c["pairs"]=pairs; save(c); out << "Saved pair " << a[2] << Qt::endl; } else if((cmd=="select" && a.size()==3)||(cmd=="next" && a.size()==2)) { auto pairs=c.value("pairs").toObject(); auto names=pairs.keys(); if(names.isEmpty()) throw std::runtime_error("no pairs configured"); QString name=cmd=="select"?a[2]:names[(names.indexOf(c.value("selected").toString())+1)%names.size()]; if(!pairs.contains(name)) throw std::runtime_error("unknown pair"); c["selected"]=name; save(c); out << "Selected " << name << Qt::endl; lockedApply(); } else if(cmd=="location" && a.size()>=3) { QJsonObject loc; if(a[2]=="auto" && a.size()==3) { auto data=request(QUrl("https://ipapi.co/json/")).object(); if(data.value("error").toBool() || !data.value("latitude").isDouble() || !data.value("longitude").isDouble()) throw std::runtime_error("IP geolocation failed"); QStringList label; for(auto key:{"city","region","country_name"}) if(!data.value(key).toString().isEmpty()) label<<data.value(key).toString(); loc=coords(data.value("latitude").toDouble(),data.value("longitude").toDouble(),label.join(", ")); } else if(a[2]=="coords" && a.size()==5) { bool ok1,ok2; double lat=a[3].toDouble(&ok1),lon=a[4].toDouble(&ok2); if(!ok1||!ok2) throw std::runtime_error("invalid coordinates"); loc=coords(lat,lon,"manual coordinates"); } else if(a[2]=="search" && a.size()>=4) { QUrl url("https://nominatim.openstreetmap.org/search"); QUrlQuery q; q.addQueryItem("q",a.mid(3).join(' ')); q.addQueryItem("format","jsonv2"); q.addQueryItem("limit","5"); url.setQuery(q); auto results=request(url).array(); if(results.size()!=1) { err << (results.isEmpty()?"No matches.\n":"Multiple matches; be more specific or use coordinates:\n"); for(auto v:results) { auto o=v.toObject(); err << o["display_name"].toString() << " " << o["lat"].toString() << " " << o["lon"].toString() << Qt::endl; } return 1; } auto o=results[0].toObject(); bool x,y; double lat=o["lat"].toString().toDouble(&x),lon=o["lon"].toString().toDouble(&y); if(!x||!y) throw std::runtime_error("invalid location response"); loc=coords(lat,lon,o["display_name"].toString()); } else throw std::runtime_error("invalid location command"); c["location"]=loc; save(c); out << "Location: " << loc["label"].toString() << " " << loc["latitude"].toDouble() << " " << loc["longitude"].toDouble() << Qt::endl; } else throw std::runtime_error("invalid command or arguments"); return 0; }
#ifndef CIRCADIAN_TEST
int main(int argc,char **argv) { QCoreApplication app(argc,argv); try { return mainImpl(app.arguments()); } catch(const std::exception &e) { err << "circadian: " << e.what() << Qt::endl; return 1; } }
#endif
